-- Курс 93: Менеджер маркетплейсов с нуля: Wildberries и Ozon с ИИ — от карточки до прибыли. Редакционная программа, сразу готова к продаже.
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (93,'Менеджер маркетплейсов с нуля: Wildberries и Ozon с ИИ — от карточки до прибыли','marketplaces','adult',48,8,27,'Профессия, которой не хватает на рынке: менеджер маркетплейсов ведёт магазины продавцов на Wildberries, Ozon и Яндекс Маркете. Учимся выбирать нишу по данным, считать юнит-экономику, создавать карточки, которые находят и покупают, работать с поставками, рекламой и отзывами. Нейросети встроены в каждый этап: тексты карточек, инфографика, анализ конкурентов, ответы на отзывы. 8 модулей, 48 уроков, в финале — разбор реального магазина и портфолио.','["Выбираете нишу и товар по данным, а не по интуиции", "Считаете юнит-экономику с учётом комиссий, логистики и рекламы", "Создаёте карточки товара с SEO, инфографикой и продающим текстом с помощью ИИ", "Планируете поставки FBO и FBS и не теряете деньги на хранении", "Настраиваете внутреннюю рекламу и следите за её окупаемостью", "Ведёте магазин как менеджер: аналитика, отзывы, акции, отчёт продавцу"]'::jsonb,'Взрослые, кто хочет удалённую профессию с понятным спросом: менеджер маркетплейсов на найме или фрилансе, а также предприниматели, которые запускают свой магазин.','["специальных знаний не требуется", "уверенная работа с компьютером и таблицами", "желание разбираться в цифрах"]'::jsonb,'Каждый модуль — этап реального запуска магазина. Учимся на живых цифрах и примерах карточек, ИИ-наставник проверяет расчёты и тексты. Нейросети используются как рабочий инструмент на каждом шаге.','Итоговый проект: полный разбор магазина — ниша, юнит-экономика, три карточки, план поставок и рекламы, отчёт для продавца.',true,'editorial_manual',1,false,'18+');

INSERT INTO t_p78828167_tutor_platform_1.course_lessons (course_id,module_index,module_title,module_description,lesson_index,lesson_title,lesson_summary,lesson_type,estimated_minutes,topics,skills_acquired,homework_description,is_preview,sort_order)
SELECT 93,
  m.mi::int,
  m.mod->>'t',
  m.mod->>'d',
  l.li::int,
  l.les->>0,
  l.les->>1,
  l.les->>2,
  CASE l.les->>2 WHEN 'theory' THEN 30 WHEN 'project' THEN 45 ELSE 40 END,
  l.les->3,
  '[]'::jsonb,
  'Выполните задание урока «' || (l.les->>0) || '» и сохраните результат в портфолио курса.',
  (m.mi = 1 AND l.li = 1),
  ((m.mi - 1) * 6 + l.li)::int
FROM jsonb_array_elements('[{"t": "Модуль 1. Профессия и рынок маркетплейсов", "d": "Как устроены площадки и чем занимается менеджер.", "l": [["Рынок маркетплейсов в России", "Сколько продаётся, кто покупает и куда растёт рынок.", "theory", ["Рынок", "Wildberries", "Ozon", "Яндекс Маркет"]], ["Кто такой менеджер маркетплейсов", "Обязанности, доход, найм и фриланс.", "theory", ["Профессия", "Обязанности", "Доход", "Карьера"]], ["Как площадка зарабатывает и что берёт с продавца", "Комиссии, логистика, хранение, штрафы.", "theory", ["Комиссии", "Логистика", "Хранение", "Штрафы"]], ["Юридическая база продавца", "ИП, самозанятость, маркировка и сертификаты.", "theory", ["ИП", "Налоги", "Честный знак", "Сертификаты"]], ["Личный кабинет продавца", "Обзор кабинетов WB и Ozon: где что лежит.", "practice", ["Кабинет", "Разделы", "Отчёты", "Настройки"]], ["Практика: карта процессов магазина", "Рисуем путь товара от поставщика до покупателя.", "practice", ["Процессы", "Поставщик", "Склад", "Покупатель"]]]}, {"t": "Модуль 2. Ниша и товар по данным", "d": "Как выбрать то, что будут покупать.", "l": [["Критерии хорошей ниши", "Спрос, конкуренция, сезонность, маржа.", "theory", ["Спрос", "Конкуренция", "Сезонность", "Маржа"]], ["Сервисы аналитики", "MPStats, Moneyplace и бесплатные способы.", "theory", ["Аналитика", "MPStats", "Moneyplace", "Данные"]], ["Анализ конкурентов с ИИ", "Нейросеть разбирает отзывы и находит слабые места конкурентов.", "practice", ["Конкуренты", "Отзывы", "ИИ-анализ", "Боли покупателей"]], ["Поиск поставщика", "Россия, Китай, производство: как проверить и договориться.", "theory", ["Поставщик", "Китай", "Проверка", "Образцы"]], ["Сезонность и прогноз спроса", "Когда закупать и когда распродавать.", "practice", ["Сезонность", "Прогноз", "Закупка", "Распродажа"]], ["Практика: отчёт по нише", "Полный анализ одной ниши с выводом «заходить или нет».", "practice", ["Отчёт", "Решение", "Риски", "Потенциал"]]]}, {"t": "Модуль 3. Юнит-экономика", "d": "Считаем, сколько остаётся с каждой продажи.", "l": [["Что такое юнит-экономика", "Почему без неё магазин работает в минус.", "theory", ["Юнит-экономика", "Себестоимость", "Прибыль", "Маржа"]], ["Все расходы продавца", "Комиссия, логистика, возвраты, хранение, реклама, налоги.", "theory", ["Расходы", "Возвраты", "Налоги", "Реклама"]], ["Калькулятор юнит-экономики в таблице", "Собираем рабочий калькулятор.", "practice", ["Таблица", "Формулы", "Калькулятор", "Сценарии"]], ["Цена и скидки", "Как назначить цену и не уйти в минус на акциях.", "practice", ["Цена", "Скидки", "Акции", "СПП"]], ["FBO или FBS: что выгоднее", "Сравнение схем по деньгам и рискам.", "theory", ["FBO", "FBS", "Склад", "Риски"]], ["Практика: экономика трёх товаров", "Считаем и выбираем лучший товар для старта.", "practice", ["Расчёт", "Сравнение", "Решение", "Бюджет"]]]}, {"t": "Модуль 4. Карточка товара, которая продаёт", "d": "Чтобы карточку нашли и купили.", "l": [["Как работает поиск на маркетплейсе", "Ключевые слова, ранжирование, релевантность.", "theory", ["Поиск", "Ранжирование", "Ключи", "Релевантность"]], ["Семантическое ядро карточки", "Собираем запросы покупателей.", "practice", ["Семантика", "Запросы", "Частотность", "Кластеры"]], ["Название и описание с ИИ", "Нейросеть пишет SEO-текст, вы проверяете.", "practice", ["Название", "Описание", "SEO", "ИИ-текст"]], ["Инфографика и фото", "Что должно быть на слайдах; генерация с нейросетями.", "practice", ["Инфографика", "Фото", "Слайды", "Генерация"]], ["Характеристики и rich-контент", "Заполняем всё, что влияет на показы.", "practice", ["Характеристики", "Rich-контент", "Видео", "Фильтры"]], ["Практика: карточка с нуля", "Полная карточка товара с ИИ-помощником.", "practice", ["Карточка", "Тексты", "Слайды", "Проверка"]]]}, {"t": "Модуль 5. Поставки и склад", "d": "Товар должен быть в наличии, но не лежать мёртвым грузом.", "l": [["Планирование поставок", "Сколько везти и на какие склады.", "theory", ["Поставки", "Склады", "Регионы", "Оборачиваемость"]], ["Оформление поставки", "Пошагово в кабинетах WB и Ozon.", "practice", ["Поставка", "Короба", "Этикетки", "Приёмка"]], ["Остатки и оборачиваемость", "Как не платить за хранение лишнего.", "practice", ["Остатки", "Оборачиваемость", "Хранение", "Неликвид"]], ["Возвраты и брак", "Что делать с возвратами и как снизить их долю.", "theory", ["Возвраты", "Брак", "Причины", "Снижение"]], ["Маркировка и документы", "Честный знак и сертификация на практике.", "theory", ["Маркировка", "Документы", "Проверки", "Штрафы"]], ["Практика: план поставок на месяц", "Таблица поставок с учётом спроса.", "practice", ["План", "Таблица", "Спрос", "Бюджет"]]]}, {"t": "Модуль 6. Продвижение и реклама", "d": "Как получить продажи и не слить бюджет.", "l": [["Органика: как подняться в выдаче", "Конверсия, отзывы, скорость доставки.", "theory", ["Органика", "Конверсия", "Выдача", "Факторы"]], ["Внутренняя реклама WB", "Аукцион, автореклама, ставки.", "practice", ["Реклама WB", "Аукцион", "Ставки", "Автореклама"]], ["Реклама на Ozon", "Трафареты, продвижение в поиске, оплата за заказ.", "practice", ["Реклама Ozon", "Трафареты", "Поиск", "Оплата за заказ"]], ["ДРР и окупаемость рекламы", "Как понять, что реклама приносит прибыль.", "practice", ["ДРР", "ROI", "Метрики", "Оптимизация"]], ["Акции площадки и внешний трафик", "Участвовать ли в акциях и когда звать блогеров.", "theory", ["Акции", "Блогеры", "Внешний трафик", "Риски"]], ["Практика: рекламная кампания", "Запускаем и оптимизируем по цифрам.", "practice", ["Кампания", "Запуск", "Анализ", "Оптимизация"]]]}, {"t": "Модуль 7. Аналитика и работа с покупателями", "d": "Ведём магазин как управляющий.", "l": [["Ключевые отчёты продавца", "Продажи, остатки, финансовый отчёт.", "practice", ["Отчёты", "Продажи", "Финансы", "Остатки"]], ["Воронка карточки", "Показы → переходы → корзина → заказ.", "practice", ["Воронка", "CTR", "Корзина", "Заказы"]], ["Отзывы и вопросы с ИИ", "Нейросеть готовит ответы в тоне бренда.", "practice", ["Отзывы", "Вопросы", "ИИ-ответы", "Репутация"]], ["Работа с негативом", "Как плохой отзыв превратить в плюс.", "theory", ["Негатив", "Претензии", "Решение", "Репутация"]], ["Автоматизация рутины", "Таблицы, уведомления и ИИ-помощники менеджера.", "practice", ["Автоматизация", "Уведомления", "Таблицы", "ИИ"]], ["Практика: еженедельный отчёт продавцу", "Отчёт, который ценит заказчик.", "practice", ["Отчёт", "Выводы", "Рекомендации", "Цифры"]]]}, {"t": "Модуль 8. Профессия: работа и заказы", "d": "Выходим на доход.", "l": [["Форматы работы менеджера", "Найм, фриланс, процент от продаж.", "theory", ["Найм", "Фриланс", "Процент", "Договор"]], ["Резюме и портфолио", "Как показать результат без опыта.", "practice", ["Резюме", "Портфолио", "Кейсы", "Цифры"]], ["Где искать работу и клиентов", "Вакансии, чаты селлеров, сарафан.", "theory", ["Вакансии", "Чаты", "Клиенты", "Сарафан"]], ["Собеседование и тестовое задание", "Что спрашивают и как пройти.", "practice", ["Собеседование", "Тестовое", "Вопросы", "Разбор"]], ["Как вести нескольких продавцов", "Система, чтобы не утонуть.", "theory", ["Клиенты", "Система", "Календарь", "Отчёты"]], ["Итоговый проект: разбор магазина", "Ниша, экономика, карточки, план — защита.", "project", ["Итоговый проект", "Магазин", "План", "Защита"]]]}]'::jsonb) WITH ORDINALITY AS m(mod, mi)
CROSS JOIN LATERAL jsonb_array_elements(m.mod->'l') WITH ORDINALITY AS l(les, li);